"use client";import {useState} from 'react';type Item={id:string;title:string;description?:string;content?:string;difficulty?:string;points?:number;module_id?:string;is_published?:boolean};export default function AdminEditor({kind,initial,modules}:{kind:'challenges'|'lessons',initial:Item[],modules:{id:string;title:string}[]}){const[items,setItems]=useState(initial),[edit,setEdit]=useState<Partial<Item>>({title:'',description:'',content:'',difficulty:'easy',points:100,is_published:false,module_id:modules[0]?.id}),[msg,setMsg]=useState('');async function save(){const r=await fetch('/api/admin/content',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind,item:edit})});const d=await r.json();setMsg(d.error||'Tersimpan');if(r.ok)location.reload()}async function remove(id:string){if(!confirm('Hapus item?'))return;const r=await fetch('/api/admin/content',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind,id})});if(r.ok)setItems(items.filter(x=>x.id!==id));else setMsg('Gagal menghapus')}return <><div className="panel space-y-2"><h2>{edit.id?'Edit':'Tambah'} {kind}</h2><label>Judul</label><input value={edit.title||''} onChange={e=>setEdit({...edit,title:e.target.value})}/><label>Modul</label><select value={edit.module_id||''} onChange={e=>setEdit({...edit,module_id:e.target.value})}>{modules.map(m=><option key={m.id} value={m.id}>{m.title}</option>)}</select><label>{kind==='lessons'?'Isi materi':'Skenario tantangan'}</label><textarea rows={6} value={(kind==='lessons'?edit.content:edit.description)||''} onChange={e=>setEdit({...edit,[kind==='lessons'?'content':'description']:e.target.value})}/>{kind==='challenges'&&<><label>Level</label><select value={edit.difficulty||'easy'} onChange={e=>setEdit({...edit,difficulty:e.target.value})}>{['easy','medium','hard'].map(x=><option key={x}>{x}</option>)}</select><label>XP</label><input type="number" value={edit.points||100} onChange={e=>setEdit({...edit,points:Number(e.target.value)})}/><p className="muted text-sm">Flag dibuat melalui SQL/admin trusted workflow, bukan browser editor.</p></>}<label className="flex gap-2"><input type="checkbox" className="w-auto" checked={!!edit.is_published} onChange={e=>setEdit({...edit,is_published:e.target.checked})}/>Publikasikan</label><button onClick={save}>Simpan</button><p>{msg}</p></div><div className="mt-5 space-y-2">{items.map(x=><div key={x.id} className="panel flex justify-between items-center gap-2"><span>{x.title} {x.is_published?'(publik)':'(draft)'}</span><div className="flex gap-2"><button onClick={()=>setEdit(x)}>Edit</button><button onClick={()=>remove(x.id)}>Hapus</button></div></div>)}</div></>}